import json, os, re, sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

BASE = r"D:/repository"
SKIP_DIRS = {'node_modules','.git','dist','build','OpenViking','skills','all','.idea','.vscode','coverage','unpackage'}
EXTS = {'.vue','.js','.ts','.jsx','.tsx','.scss','.css','.less','.json','.mjs','.html','.py','.mjs'}

# index all text files
files = []
for root, dirs, fns in os.walk(BASE):
    dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
    for fn in fns:
        if os.path.splitext(fn)[1].lower() in EXTS:
            p = os.path.join(root, fn)
            try:
                if os.path.getsize(p) > 3_000_000: continue
            except OSError:
                continue
            files.append(p)

# preload contents lazily via cache
content_cache = {}
def readfile(p):
    if p in content_cache: return content_cache[p]
    try:
        with open(p, encoding='utf-8', errors='ignore') as f:
            c = f.read()
    except OSError:
        c = ''
    content_cache[p] = c
    return c

def basename_hits(bn):
    return [p for p in files if os.path.basename(p).lower() == bn.lower()]

def token_hits(tok, maxout=3):
    out = []
    low = tok.lower()
    for p in files:
        c = readfile(p)
        if low in c.lower():
            out.append(p)
            if len(out) >= maxout: break
    return out

d = json.load(open(r"C:/Users/Administrator/.dsh/cache/memory-audit/select.json", encoding='utf-8'))
for i, c in enumerate(d['candidates'], 1):
    body = c['content'].replace('\\n','\n')
    # file basenames mentioned
    fns = set(re.findall(r'[\w\-./]+\.(?:vue|js|ts|scss|css|json|mjs)', body))
    fns = {os.path.basename(f) for f in fns}
    # backtick identifiers
    ticks = re.findall(r'`([^`]+)`', body)
    ident = set()
    for t in ticks:
        for m in re.findall(r'[A-Za-z_$][A-Za-z0-9_$]{5,}', t):
            ident.add(m)
    # camelCase/pascal tokens in body
    for m in re.findall(r'\b[a-z][a-zA-Z0-9]{7,}\b', body):
        if any(x.isupper() for x in m[1:]):
            ident.add(m)
    # drop generic
    generic = {'所属项目','来源会话','代码基线','验证证据','extracted','cursor','project','session'}
    ident = {x for x in ident if x.lower() not in {g.lower() for g in generic}}
    print(f"### {i:02d} {c['uri'].split('/memories/')[-1]} sha={c['body_sha256_16']}")
    for bn in sorted(fns)[:8]:
        h = basename_hits(bn)
        print(f"  FILE {bn}: {len(h)} | {h[0] if h else ''}")
    for tk in sorted(ident)[:12]:
        h = token_hits(tk, 3)
        print(f"  TOK  {tk}: {len(h)}+ | {h[0] if h else ''}")
print("TOTAL_FILES", len(files))

